// Example: transform a SDK stream into both an AsyncIterator and a ReadableStream
// Usage (Node): for await (const chunk of handle.asAsyncIterator()) { process(chunk) }
// Usage (Browser): fetch(...).then(res => res.body.pipeTo(handle.asWebStream()))

class ResumableStreamHandle<T> {
  // pseudo-API sketch — actual SDK will be exported from @redwood/sdk-streaming
  asAsyncIterator(): AsyncGenerator<T, void, unknown> { /* returns an async generator reading from internal queue */ }
  asWebStream(): ReadableStream<T> { /* returns a ReadableStream adapter */ }
  cancel(reason?: string): void { /* propagate cancellation */ }
  getResumeToken(): string | null { /* last known resume token if available */ }
}

// Consumer example (Node)
async function consumeNode(handle) {
  try {
    for await (const delta of handle.asAsyncIterator()) {
      console.log('delta', delta.text)
    }
  } catch (err) {
    console.error('stream failed', err)
    // If transient we can try resume
    const token = handle.getResumeToken()
    if (token) {
      const resumed = await client.resumeStream(token) // SDK helper to attempt resume
      if (resumed) return consumeNode(resumed)
    }
  }
}

// Consumer example (Browser)
function consumeBrowser(handle) {
  const sink = new WritableStream({
    write(chunk) { renderChunk(chunk) },
    abort(reason) { console.warn('consumer aborted', reason) }
  })
  handle.asWebStream().pipeTo(sink).catch(async err => {
    console.error('pipe failed', err)
    // try resume path same as above
  })
}

